/**
 * ai_dynamic.js
 * 
 * Interactive controller for the "Dynamically generated by AI" section.
 * Supports category switching, custom prompt input, live model selection,
 * witty loading status cycle, rate limiting cooldown timers, and Markdown rendering.
 */

document.addEventListener('DOMContentLoaded', () => {
    const section = document.getElementById('ai_dynamic');
    if (!section) return;

    const catButtons        = section.querySelectorAll('.ai-cat-btn');
    const generateBtn       = document.getElementById('ai_dynamic_generate_btn');
    const modelSelect       = document.getElementById('ai_dynamic_model');
    const customWrap        = document.getElementById('ai_dynamic_custom_wrap');
    const customInput       = document.getElementById('ai_dynamic_custom_input');
    const loadingWrap       = document.getElementById('ai_dynamic_loading');
    const statusText        = document.getElementById('ai_dynamic_status_text');
    const contentWrap       = document.getElementById('ai_dynamic_content');
    const topicLabel        = document.getElementById('ai_dynamic_topic_label');
    const usedModelTag      = document.getElementById('ai_dynamic_used_model');
    const copyBtn           = document.getElementById('ai_dynamic_copy_btn');
    const rateLimitText     = document.getElementById('ai_dynamic_ratelimit_text');
    const cooldownBanner    = document.getElementById('ai_dynamic_cooldown_banner');
    const cooldownText      = document.getElementById('ai_dynamic_cooldown_text');

    let currentCategory = 'roast_domains';
    let currentRawMarkdown = contentWrap ? contentWrap.innerText : '';
    let isLoading = false;
    let loadingInterval = null;
    let cooldownTimer = null;

    const topicLabels = {
        'roast_domains': '🌐 Roast Domains',
        'dev_wisdom': '💡 Dev Wisdom',
        'homelab_idea': '🖥️ Homelab Idea',
        'mail_free': '✉️ mail-free.de Eulogy',
        'hot_take': '🔥 Hot Take',
        'custom': '⚡ Custom Topic'
    };

    const loadingPhrases = [
        'Consulting the neural nodes...',
        'Scanning 50+ dormant domains...',
        'Formulating cynical dev wisdom...',
        'Benchmarking homelab servers...',
        'Parsing commented-out PHP blocks...',
        'Calculating existential developer dread...',
        'Negotiating DNS propagation...',
        'Synthesizing pure developer sarcasm...'
    ];

    // Session UUID
    function getSessionId() {
        let sid = sessionStorage.getItem('ai_dynamic_session_id');
        if (!sid) {
            sid = 'dyn_' + Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
            sessionStorage.setItem('ai_dynamic_session_id', sid);
        }
        return sid;
    }

    // Category button handling
    catButtons.forEach(btn => {
        btn.addEventListener('click', () => {
            if (isLoading) return;
            const cat = btn.dataset.category;
            if (!cat) return;

            catButtons.forEach(b => {
                b.classList.remove('active');
                b.setAttribute('aria-selected', 'false');
            });
            btn.classList.add('active');
            btn.setAttribute('aria-selected', 'true');

            currentCategory = cat;
            if (topicLabel) {
                topicLabel.textContent = topicLabels[cat] || cat;
            }

            if (cat === 'custom') {
                if (customWrap) {
                    customWrap.style.display = 'block';
                    if (customInput) customInput.focus();
                }
            } else {
                if (customWrap) {
                    customWrap.style.display = 'none';
                }
                // Auto trigger generation on category switch
                triggerGenerate(false);
            }
        });
    });

    // Enter key inside custom prompt
    if (customInput) {
        customInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                triggerGenerate(true);
            }
        });
    }

    // Generate Button
    if (generateBtn) {
        generateBtn.addEventListener('click', () => {
            triggerGenerate(true);
        });
    }

    // Model selection change
    if (modelSelect && modelSelect.tagName === 'SELECT') {
        modelSelect.addEventListener('change', () => {
            triggerGenerate(true);
        });
    }

    // Copy Button handling
    if (copyBtn) {
        copyBtn.addEventListener('click', async () => {
            const textToCopy = currentRawMarkdown || (contentWrap ? contentWrap.innerText : '');
            if (!textToCopy) return;

            let success = false;
            if (navigator.clipboard && window.isSecureContext) {
                try {
                    await navigator.clipboard.writeText(textToCopy);
                    success = true;
                } catch (e) {
                    console.error('Clipboard copy failed:', e);
                }
            }

            if (!success) {
                // Fallback copy
                const ta = document.createElement('textarea');
                ta.value = textToCopy;
                ta.style.position = 'fixed';
                ta.style.left = '-9999px';
                document.body.appendChild(ta);
                ta.select();
                try {
                    success = document.execCommand('copy');
                } catch (e) {}
                document.body.removeChild(ta);
            }

            if (success) {
                const iconCopy = copyBtn.querySelector('.icon-copy');
                const iconCheck = copyBtn.querySelector('.icon-check');
                const textSpan = copyBtn.querySelector('.copy-text');

                if (iconCopy) iconCopy.style.display = 'none';
                if (iconCheck) iconCheck.style.display = 'inline-block';
                if (textSpan) textSpan.textContent = 'Copied!';

                setTimeout(() => {
                    if (iconCopy) iconCopy.style.display = 'inline-block';
                    if (iconCheck) iconCheck.style.display = 'none';
                    if (textSpan) textSpan.textContent = 'Copy';
                }, 2000);
            }
        });
    }

    /**
     * Start cooldown timer when rate limited
     */
    function startCooldown(seconds) {
        if (cooldownTimer) clearInterval(cooldownTimer);
        if (!cooldownBanner || !cooldownText) return;

        cooldownBanner.style.display = 'inline-flex';
        if (generateBtn) generateBtn.disabled = true;

        let remaining = Math.max(1, seconds);
        const updateText = () => {
            cooldownText.textContent = `Rate limit active. Cooldown resets in ${remaining}s.`;
        };
        updateText();

        cooldownTimer = setInterval(() => {
            remaining--;
            if (remaining <= 0) {
                clearInterval(cooldownTimer);
                cooldownTimer = null;
                cooldownBanner.style.display = 'none';
                if (generateBtn) generateBtn.disabled = false;
                if (rateLimitText) {
                    rateLimitText.textContent = 'Generations available';
                }
            } else {
                updateText();
            }
        }, 1000);
    }

    /**
     * Main dynamic AI generation dispatcher
     */
    async function triggerGenerate(forceFresh = false) {
        if (isLoading) return;

        const model = modelSelect ? modelSelect.value : null;
        const promptVal = (currentCategory === 'custom' && customInput) ? customInput.value.trim() : '';

        // UI Loading State
        isLoading = true;
        if (generateBtn) {
            generateBtn.disabled = true;
            generateBtn.classList.add('is-loading');
        }
        if (contentWrap) contentWrap.style.display = 'none';
        if (loadingWrap) loadingWrap.style.display = 'flex';

        // Rotate loading phrases
        let phraseIdx = 0;
        if (statusText) {
            statusText.textContent = loadingPhrases[0];
            loadingInterval = setInterval(() => {
                phraseIdx = (phraseIdx + 1) % loadingPhrases.length;
                statusText.textContent = loadingPhrases[phraseIdx];
            }, 1600);
        }

        const apiEndpoint = '/api/v1/ai/dynamic';
        const payload = {
            category: currentCategory,
            prompt: promptVal,
            model: model,
            session_id: getSessionId(),
            fresh: forceFresh
        };

        try {
            const response = await fetch(apiEndpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json'
                },
                body: JSON.stringify(payload)
            });

            const data = await response.json();

            // Rate Limit metadata inspection
            if (data.meta && data.meta.rate_limit && rateLimitText) {
                const rl = data.meta.rate_limit;
                rateLimitText.textContent = `${rl.remaining} / ${rl.limit} generations available this minute`;
            }

            if (response.status === 429 || (data.error && data.error.code === 'TOO_MANY_REQUESTS')) {
                const retryAfter = data.error?.retry_after || 60;
                startCooldown(retryAfter);
                if (contentWrap) {
                    contentWrap.innerHTML = `<div class="ai-rate-limit-warning"><strong>⚡ Rate Limit Reached</strong><p>${data.error?.message || 'Please wait before generating more dynamic content.'}</p></div>`;
                }
                return;
            }

            if (!response.ok || !data.success) {
                const errMsg = data.error?.message || 'Failed to generate dynamic content.';
                if (contentWrap) {
                    contentWrap.innerHTML = `<div class="ai-error-notice"><strong>Notice:</strong> ${errMsg}</div>`;
                }
                return;
            }

            const item = data.data || {};
            currentRawMarkdown = item.content || '';

            if (contentWrap) {
                if (window.parseMarkdown) {
                    contentWrap.innerHTML = window.parseMarkdown(currentRawMarkdown);
                } else {
                    contentWrap.textContent = currentRawMarkdown;
                }
            }

            if (usedModelTag && item.model) {
                const modelName = item.model.split('/').pop().replace(':free', '');
                usedModelTag.textContent = modelName;
            }

        } catch (err) {
            console.error('Dynamic AI fetch error:', err);
            if (contentWrap) {
                contentWrap.innerHTML = `<div class="ai-error-notice"><strong>Network Error:</strong> Unable to connect to AI service. Please try again.</div>`;
            }
        } finally {
            if (loadingInterval) {
                clearInterval(loadingInterval);
                loadingInterval = null;
            }
            isLoading = false;
            if (loadingWrap) loadingWrap.style.display = 'none';
            if (contentWrap) contentWrap.style.display = 'block';
            if (generateBtn && !cooldownTimer) {
                generateBtn.disabled = false;
                generateBtn.classList.remove('is-loading');
            }
        }
    }
});
